<?php
use PHPUnit\Framework\TestCase;
final class Phase9PMScheduledVisitsTest extends TestCase {
 public function test_scheduled_visit_upgrade_is_versioned_and_normalized(): void {$b=file_get_contents(__DIR__.'/../../servsys.php');$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString("SERVSYS_DB_VERSION', 14",$b);$this->assertStringContainsString('servsys_pm_scheduled_visits',$s);$this->assertStringContainsString('scheduled_year smallint(5) unsigned NOT NULL',$s);$this->assertStringContainsString('scheduled_month tinyint(3) unsigned NOT NULL',$s);$this->assertStringContainsString('scheduled_date date NULL',$s);$this->assertStringContainsString('service_call_id bigint(20) unsigned NULL',$s);$this->assertStringNotContainsString('visit1',$s);$this->assertStringNotContainsString('visit6',$s);}
 public function test_month_year_is_preserved_without_manufacturing_exact_date(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMScheduledVisitService.php');$this->assertStringContainsString("'scheduled_year'=>\$year",$p);$this->assertStringContainsString("'scheduled_month'=>\$month",$p);$this->assertStringContainsString("'scheduled_date'=>\$exact",$p);$this->assertStringContainsString("\$exact=!empty(\$data['scheduled_date'])",$p);}
 public function test_exact_date_must_match_planned_period(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMScheduledVisitService.php');$this->assertStringContainsString('Exact visit date must be within the scheduled month and year',$p);}
 public function test_service_call_must_match_agreement_customer_and_site(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMScheduledVisitService.php');$this->assertStringContainsString('Service Call must belong to the Agreement Customer and Site',$p);}
 public function test_completion_requires_completed_service_call(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMScheduledVisitService.php');$this->assertStringContainsString('A completed PM Visit requires a completed Service Call',$p);$this->assertStringContainsString("'completed'!==\$call['status']",$p);}
 public function test_linked_visit_cannot_be_deleted(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMScheduledVisitService.php');$this->assertStringContainsString('linked to a Service Call cannot be deleted. Cancel it instead.',$p);}
 public function test_repository_is_company_scoped(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMScheduledVisitRepository.php');$this->assertStringContainsString('CompanyContext::current_company_id()',$p);}
 public function test_admin_scheduling_uses_existing_pm_agreement_permission_and_nonces(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/PMAgreementsPage.php');$this->assertStringContainsString("check_admin_referer('servsys_save_pm_visit')",$p);$this->assertStringContainsString("check_admin_referer('servsys_delete_pm_visit_'.\$visit_id)",$p);$this->assertStringContainsString('Capabilities::MANAGE_PM_AGREEMENTS',$p);$this->assertStringContainsString('Month/year is the authoritative planned period',$p);}
}
